<form method="GET" class="app-unified-filter report-toolbar d-flex flex-wrap align-items-end gap-2 mb-3">
<div><label for="taxPeriod" class="form-label small">Periode</label><select id="taxPeriod" name="period_type" class="form-select form-select-sm">@foreach(['monthly'=>'Bulanan','quarterly'=>'Kuartalan','yearly'=>'Tahunan'] as $key=>$label)<option value="{{ $key }}" @selected($periodType === $key)>{{ $label }}</option>@endforeach</select></div>
<div data-tax-period="monthly" @if($periodType !== 'monthly') hidden @endif><label for="taxMonth" class="form-label small">Bulan</label><input id="taxMonth" type="month" name="month" value="{{ $month }}" class="form-control form-control-sm" @disabled($periodType !== 'monthly') required></div>
<div data-tax-period="quarterly" @if($periodType !== 'quarterly') hidden @endif><label for="taxQuarter" class="form-label small">Kuartal</label><select id="taxQuarter" name="quarter" class="form-select form-select-sm" @disabled($periodType !== 'quarterly')>@foreach([1,2,3,4] as $value)<option value="{{ $value }}" @selected($quarter === $value)>Kuartal {{ $value }}</option>@endforeach</select></div>
<div data-tax-period="quarterly yearly" @if($periodType === 'monthly') hidden @endif><label for="taxYear" class="form-label small">Tahun</label><input id="taxYear" type="number" name="year" value="{{ $year }}" min="1900" max="9999" class="form-control form-control-sm" style="width:110px" @disabled($periodType === 'monthly') required></div>
<button class="btn btn-sm btn-primary"><i class="bi bi-funnel me-1"></i>Terapkan</button><a class="btn btn-sm btn-outline-secondary" href="{{ route('taxes.index') }}" title="Bulan ini" aria-label="Bulan ini"><i class="bi bi-arrow-counterclockwise me-1" aria-hidden="true"></i>Reset</a>
</form>
@push('scripts')<script>
(() => { const select = document.getElementById('taxPeriod'); const update = () => document.querySelectorAll('[data-tax-period]').forEach(group => { const active = group.dataset.taxPeriod.split(' ').includes(select.value); group.hidden = !active; group.querySelectorAll('input,select').forEach(input => input.disabled = !active); }); select.addEventListener('change', update); update(); })();
</script>@endpush
